// ---------------------------------------------------------------------------
// Data layout is: data[k][j], with j contiguous in memory.
// We iterate k (samples) in the outer loop and j (features) in the inner loop
// to generate values while streaming one full row at a time.
void init_array(num_t &float_n, auto data) {
	using namespace noarr;

	// float_n = N (number of samples)
	float_n = static_cast<num_t>(data | get_length<'k'>());

	const auto m_len = data | get_length<'j'>();
	const num_t inv_m = static_cast<num_t>(1.0) / static_cast<num_t>(m_len);

	// k-major, j-minor traversal: this matches the physical row-major layout
	// (j dimension is contiguous), giving good cache locality.
	traverser(data).template for_dims<'k'>([&](auto tk) {
		// tk has 'k' fixed, 'j' remains
		const auto sk = tk.state();
		const num_t k_val = static_cast<num_t>(noarr::get_index<'k'>(sk));

		tk.template for_each<'j'>([&](auto state) {
			const std::size_t j_idx = noarr::get_index<'j'>(state);
			data[state] = (k_val * static_cast<num_t>(j_idx)) * inv_m;
		});
	});
}

// computation kernel
// ---------------------------------------------------------------------------
// The kernel computes:
//   1) per-feature mean: mean[j] = (1/N) * sum_k data[k][j]
//   2) centers the data: data[k][j] -= mean[j]
//   3) covariance matrix:
//        cov[i][j] = sum_k data[k][i] * data[k][j] / (N - 1)
//      and enforces symmetry: cov[j][i] = cov[i][j]
//
// Optimizations over the original version:
//   - Means are computed with k outer / j inner loops, streaming rows of data.
//   - Covariance is computed as a blocked matrix product X^T * X in the sense
//     of loop ordering: we iterate samples (k) outermost and reuse data[k][i]
//     across all j in that row, which greatly improves data locality for `data`.
//   - Divisions by N and (N-1) are replaced by multiplications with their
//     precomputed reciprocals.
[[gnu::flatten, gnu::noinline]]
void kernel_covariance(num_t float_n, auto data, auto cov, auto mean) {
	// data: k x j  (N samples, M features)
	// cov:  i x j  (M x M)
	// mean: j      (M)
	using namespace noarr;

	// view of data where the feature dimension is called 'i'
	// (for cov's row index); data_i: k x i
	auto data_i = data ^ noarr::rename<'j', 'i'>();

#pragma scop
	const num_t inv_float_n = static_cast<num_t>(1.0) / float_n;
	const num_t norm = static_cast<num_t>(1.0) / (float_n - static_cast<num_t>(1.0));

	// -----------------------------------------------------------------------
	// 1) mean[j] = (1/N) * sum_k data[k][j]
	// -----------------------------------------------------------------------

	// 1a) initialize mean[j] = 0 for all features
	traverser(mean).for_each([&](auto sj) {
		mean[sj] = static_cast<num_t>(0);
	});

	// 1b) accumulate sums with k-major, j-minor traversal
	//     This streams rows: for each sample k, we traverse all features j.
	traverser(data, mean).template for_dims<'k'>([=](auto tk) {
		// tk has 'k' fixed, 'j' remains
		tk.template for_each<'j'>([=](auto state) {
			// state contains 'k' and 'j'; mean ignores 'k'
			mean[state] += data[state];
		});
	});

	// 1c) scale by 1/N
	traverser(mean).for_each([=](auto sj) {
		mean[sj] *= inv_float_n;
	});

	// -----------------------------------------------------------------------
	// 2) data[k][j] -= mean[j]
	// -----------------------------------------------------------------------
	// Again, we traverse k-major / j-minor to stream rows of `data`.
	traverser(data, mean).template for_dims<'k'>([=](auto tk) {
		tk.template for_each<'j'>([=](auto state) {
			data[state] -= mean[state];
		});
	});

	// -----------------------------------------------------------------------
	// 3) covariance
	//    We compute the upper triangle (including diagonal) of:
	//       C = X^T * X / (N - 1),
	//    where X is the centered data matrix (rows: samples, cols: features).
	//
	//    Loop order:
	//      for k in samples:
	//        for i in features:
	//          xi = data[k][i];
	//          for j in features:
	//            if (j >= i) cov[i][j] += xi * data[k][j];
	//
	//    This order streams rows of data (good locality) and reuses xi across
	//    all j for fixed (k, i). We accumulate into cov[i][j], then later
	//    scale by `norm` and copy to cov[j][i] to enforce symmetry.
	// -----------------------------------------------------------------------

	// 3a) initialize covariance matrix to zero
	traverser(cov).for_each([&](auto sij) {
		cov[sij] = static_cast<num_t>(0);
	});

	// 3b) accumulate upper triangle of X^T * X
	traverser(cov, data, data_i).template for_dims<'k'>([=](auto tk) {
		// tk has 'k' fixed, 'i' and 'j' remain
		tk.template for_dims<'i'>([=](auto tki) {
			// tki has 'k' and 'i' fixed, 'j' remains
			auto s_ki = tki.state();         // contains indexes for k and i
			const num_t x_i = data_i[s_ki];  // data[k][i] via renamed view

			// inner-most loop over j (features), k and i fixed above
			tki.template for_each<'j'>([=](auto s_kij) {
				// s_kij contains 'k', 'i', 'j'
				auto [i_idx, j_idx] = get_indices<'i', 'j'>(s_kij);

				// Only accumulate upper triangle: j >= i
				if (j_idx < i_idx)
					return;

				// State for cov: only (i, j) indices are needed
				auto s_ij = noarr::idx<'i', 'j'>(i_idx, j_idx);

				// cov[i][j] += data[k][i] * data[k][j]
				cov[s_ij] += x_i * data[s_kij];
			});
		});
	});

	// 3c) normalize by (N - 1) and enforce symmetry: cov[j][i] = cov[i][j]
	traverser(cov).template for_dims<'i'>([=](auto ti) {
		ti.template for_each<'j'>([=](auto s_ij) {
			auto [i_idx, j_idx] = get_indices<'i', 'j'>(s_ij);

			// work only on upper triangle (including diagonal)
			if (j_idx < i_idx)
				return;

			// scale cov[i][j]
			cov[s_ij] *= norm;

			// symmetric element
			auto s_ji = noarr::idx<'i', 'j'>(j_idx, i_idx);
			cov[s_ji] = cov[s_ij];
		});
	});
#pragma endscop
}

