// - all loop nests are expressed via Noarr traversers
// - mean computation is reorganized to be row-major (k-major, j-minor)
//   while keeping the same arithmetic as the original code
// - covariance accumulation keeps the same order over k per (i,j),
//   but uses a local accumulator to avoid repeated memory traffic
[[gnu::flatten, gnu::noinline]]
void kernel_covariance(num_t float_n, auto data, auto cov, auto mean) {
	// data: k x j  (N samples, M features)
	// cov:  i x j  (M x M)
	// mean: j      (M)
	using namespace noarr;

	// view of data where the feature dimension is called 'i'
	// (for cov's row index); data_i: k x i
	auto data_i = data ^ noarr::rename<'j', 'i'>();

	const num_t n_minus_one = float_n - (num_t)1.0;

#pragma scop
	// ---------------------------------------------------------------------
	// 1) mean[j] = (1/n) * sum_k data[k][j]
	// ---------------------------------------------------------------------
	// Original version:
	//   for each j:
	//     mean[j] = 0;
	//     for each k:
	//       mean[j] += data[k][j];
	//     mean[j] /= float_n;
	//
	// We keep the same arithmetic, but reorder traversal for better
	// spatial locality in data:
	//   - first zero all mean[j]
	//   - then iterate k outer, j inner (row-major in data)
	//   - finally divide each mean[j] by float_n
	// This does not change the order of additions for a fixed j over k.
	// ---------------------------------------------------------------------

	// zero initialize mean[j]
	traverser(mean).for_each([&](auto s_j) {
		mean[s_j] = (num_t)0;
	});

	// accumulate over all samples, row-major: k outer, j inner (contiguous)
	traverser(data, mean).template for_dims<'k'>([=](auto tk) {
		tk.template for_each<'j'>([=](auto state) {
			// state carries both 'k' and 'j', but mean only uses 'j'
			mean[state] += data[state];
		});
	});

	// normalize by n (one division per feature, as in the original code)
	traverser(mean).for_each([=](auto s_j) {
		mean[s_j] /= float_n;
	});

	// ---------------------------------------------------------------------
	// 2) data[k][j] -= mean[j]
	// ---------------------------------------------------------------------
	// This step was already traversed row-major: k outer, j inner.
	// We keep the loop structure for good locality.
	// ---------------------------------------------------------------------
	traverser(data, mean).template for_dims<'k'>([=](auto tk) {
		tk.template for_each<'j'>([=](auto state) {
			data[state] -= mean[state];
		});
	});

	// ---------------------------------------------------------------------
	// 3) covariance
	//
	//    for i in 0..M-1
	//      for j in i..M-1
	//        cov[i][j] = sum_k data[k][i] * data[k][j] / (float_n - 1)
	//        cov[j][i] = cov[i][j]
	//
	// We preserve this structure (i/j outer, k inner), but:
	//   - we use a local accumulator 'acc' per (i,j) so that cov[i][j]
	//     is written exactly once, reducing memory traffic and avoiding
	//     potential aliasing issues that prevent keeping cov[i][j] in a
	//     register across the k loop.
	//   - we still only compute the upper triangle (j >= i) and mirror it.
	// ---------------------------------------------------------------------
	traverser(cov, data, data_i).template for_dims<'i'>([=](auto ti) {
		ti.template for_dims<'j'>([=](auto tij) {
			auto s_ij = tij.state();
			auto [i_idx, j_idx] = get_indices<'i', 'j'>(s_ij);

			// enforce j >= i (upper triangle, including diagonal)
			if (j_idx < i_idx)
				return;

			// local accumulator lives in a register across the k-loop
			num_t acc = (num_t)0;

			// accumulate over k (samples)
			tij.template for_each<'k'>([&](auto sk) {
				// sk carries 'k', 'i', 'j'; data ignores 'i', data_i ignores 'j'
				acc += data[sk] * data_i[sk];
			});

			// normalize
			acc /= n_minus_one;
			cov[s_ij] = acc;

			// symmetry: cov[j][i] = cov[i][j]
			// avoid redundant self-copy on the diagonal
			if (j_idx != i_idx) {
				auto s_ji = noarr::idx<'i', 'j'>(j_idx, i_idx);
				cov[s_ji] = acc;
			}
		});
	});
#pragma endscop
}

} // namespace

