	// cov:  i x j  (M x M)
	// mean: j      (M)
	using namespace noarr;

	// view of data where the feature dimension is called 'i'
	// (for cov's row index); data_i: k x i
	auto data_i = data ^ noarr::rename<'j', 'i'>();

#pragma scop
	// ------------------------------------------------------------------ //
	// 1) mean[j] = (1/n) * sum_k data[k][j]
	//
	// We compute this in three passes:
	//   a) zero mean
	//   b) accumulate over all samples, streaming data row-by-row
	//   c) scale by 1 / float_n
	//
	// Traversal order k -> j improves locality because the innermost 'j'
	// dimension is contiguous in memory for the chosen layout.
	// ------------------------------------------------------------------ //

	// 1a) initialize mean[j] = 0
	traverser(mean).for_each([&](auto sj) {
		mean[sj] = num_t(0);
	});

	// 1b) accumulate sum over samples: j is inner / contiguous
	traverser(data, mean).template for_dims<'k'>([=](auto tk) {
		tk.template for_each<'j'>([=](auto s) {
			// s has indices (k, j); mean ignores k and uses j only
			mean[s] += data[s];
		});
	});

	// 1c) scale by 1 / n (precompute reciprocal to avoid repeated division)
	const num_t inv_float_n = num_t(1) / float_n;
	traverser(mean).for_each([=](auto sj) {
		mean[sj] *= inv_float_n;
	});

	// ------------------------------------------------------------------ //
	// 2) data[k][j] -= mean[j]
	//
	// Center each feature independently. We again traverse with 'k'
	// outer and 'j' inner to keep accesses to data contiguous.
	// ------------------------------------------------------------------ //
	traverser(data, mean).template for_dims<'k'>([=](auto tk) {
		tk.template for_each<'j'>([=](auto s) {
			data[s] -= mean[s];
		});
	});

	// ------------------------------------------------------------------ //
	// 3) covariance
	//
	// After centering, covariance is:
	//   cov[i][j] = 1/(n-1) * sum_k data[k][i] * data[k][j]
	//
	// Instead of the original (i, j, k) loop ordering, we iterate
	// samples k outermost and form an outer product of each centered
	// sample with itself:
	//
	//   for k:
	//     for i:
	//       x_i = data[k][i]
	//       for j >= i:
	//         cov[i][j] += x_i * data[k][j]
	//
	// This processes each sample row while it is hot in L1, greatly
	// improving cache locality. We first zero cov, then accumulate the
	// unnormalized sums, and finally normalize and symmetrize.
	// ------------------------------------------------------------------ //

	const num_t norm = num_t(1) / (float_n - num_t(1));

	// 3a) zero covariance matrix
	traverser(cov).for_each([&](auto s_ij) {
		cov[s_ij] = num_t(0);
	});

	// 3b) accumulate upper-triangular covariance using k -> i -> j order
	traverser(cov, data, data_i).template for_dims<'k'>([=](auto tk) {
		// tk has sample index 'k' fixed; remaining logical dimensions are
		// the feature indices 'i' and 'j'.
		tk.template for_dims<'i'>([=](auto tki) {
			// State with current (k, i). We read data_i once per (k, i)
			// pair and reuse it for all j >= i.
			auto s_ki = tki.state();
			num_t x_i = data_i[s_ki];

			tki.template for_dims<'j'>([=](auto tkij) {
				auto s_ij_k = tkij.state();
				auto [i_idx, j_idx] = get_indices<'i', 'j'>(s_ij_k);

				// Only compute upper triangle (including the diagonal).
				if (j_idx < i_idx)
					return;

				// cov[i][j] += data[k][i] * data[k][j]
				cov[s_ij_k] += x_i * data[s_ij_k];
			});
		});
	});

	// 3c) normalize and enforce symmetry: cov[j][i] = cov[i][j]
	traverser(cov).template for_dims<'i'>([=](auto ti) {
		ti.template for_dims<'j'>([=](auto tij) {
			auto s_ij = tij.state();
			auto [i_idx, j_idx] = get_indices<'i', 'j'>(s_ij);

			if (j_idx < i_idx)
				return;

			// Normalize upper triangular element
			cov[s_ij] *= norm;

			// Copy to the symmetric position for strictly lower triangle.
			if (j_idx != i_idx) {
				auto s_ji = noarr::idx<'i', 'j'>(j_idx, i_idx);
				cov[s_ji] = cov[s_ij];
			}
