	// (for cov's row index); data_i: k x i
	auto data_i = data ^ noarr::rename<'j', 'i'>();

#pragma scop
	// ------------------------------------------------------------------
	// 1) mean[j] = (1/n) * sum_k data[k][j]
	//    We accumulate into a scalar and write mean[j] once, instead
	//    of repeatedly updating mean[j] inside the k-loop.
	// ------------------------------------------------------------------
	const num_t inv_float_n = num_t(1.0) / float_n;

	traverser(data, mean).template for_dims<'j'>([&](auto tj) {
		// tj: traverser with 'j' fixed, iterating over 'k'
		num_t sum = num_t(0);

		tj.template for_each<'k'>([&](auto state) {
			sum += data[state];
		});

		// mean index is given by the fixed 'j' in tj
		mean[tj] = sum * inv_float_n;
	});

	// ------------------------------------------------------------------
	// 2) Center the data: data[k][j] -= mean[j]
	//    Traversal order: k-major, j-minor, so we walk each sample's
	//    feature vector contiguously in memory.
	// ------------------------------------------------------------------
	traverser(data, mean).template for_dims<'k'>([&](auto tk) {
		tk.template for_each<'j'>([&](auto state) {
			// state contains {k, j}; mean only depends on 'j'
			data[state] -= mean[state];
		});
	});

