	//      for i
	//        for j
	//          for k
	//            cov[i][j] += data[k][i] * data[k][j]
	//
	//    Here we restructure the loops to:
	//      for k           (samples / rows of X)
	//        for i         (feature index for X[k][i])
	//          load X[k][i] once
	//          for j>=i    (other features)
	//            load X[k][j]
	//            cov[i][j] += X[k][i] * X[k][j]
