	//       cov[i][j] = cov[j][i] = cov[i][j] / (n - 1), for all i <= j
	//    This uses the same accumulation order per (i,j) pair as the
	//    original kernel, so floating-point rounding behaviour matches.
	traverser(cov).template for_dims<'i'>([&](auto ti) {
		ti.template for_dims<'j'>([&](auto tij) {
			auto s_ij = tij.state();
